def interpret_expression(self, expr, local_vars, allow_recursion):
    ret, should_return = self.interpret_statement(expr, local_vars, allow_recursion)
    if should_return:
        raise self.Exception('Cannot return from an expression', expr)
    return ret

def extract_object(self, objname):
    _FUNC_NAME_RE = r'''(?:[a-zA-Z$0-9]+|"[a-zA-Z$0-9]+"|'[a-zA-Z$0-9]+')'''
    obj = {}
    obj_m = re.search(
        r'''(?x)
            (?<!\.)%s\s*=\s*{\s*
                (?P<fields>(%s\s*:\s*function\s*\(.*?\)\s*{.*?}(?:,\s*)?)*)
            }\s*;
        ''' % (re.escape(objname), _FUNC_NAME_RE),
        self.code)
    if not obj_m:
        raise self.Exception(f'Could not find object {objname}')
    fields = obj_m.group('fields')
    # Currently, it only supports function definitions
    fields_m = re.finditer(
        r'''(?x)
            (?P<key>%s)\s*:\s*function\s*\((?P<args>(?:%s|,)*)\){(?P<code>[^}]+)}
        ''' % (_FUNC_NAME_RE, _NAME_RE),
        fields)
    for f in fields_m:
        argnames = f.group('args').split(',')
        name = remove_quotes(f.group('key'))
        obj[name] = function_with_repr(self.build_function(argnames, f.group('code')), f'F<{name}>')

    return obj

def extract_function_code(self, funcname):
    """ @returns argnames, code """
    func_m = re.search(
        r'''(?xs)
            (?:
                function\s+%(name)s|
                [{;,]\s*%(name)s\s*=\s*function|
                (?:var|const|let)\s+%(name)s\s*=\s*function
            )\s*
            \((?P<args>[^)]*)\)\s*
            (?P<code>{.+})''' % {'name': re.escape(funcname)},
        self.code)
    if func_m is None:
        raise self.Exception(f'Could not find JS function "{funcname}"')
    code, _ = self._separate_at_paren(func_m.group('code'))
    return [x.strip() for x in func_m.group('args').split(',')], code

def extract_function(self, funcname, *global_stack):
    return function_with_repr(
        self.extract_function_from_code(*self.extract_function_code(funcname), *global_stack),
        f'F<{funcname}>')

def extract_function_from_code(self, argnames, code, *global_stack):
    local_vars = {}
    while True:
        mobj = re.search(r'function\((?P<args>[^)]*)\)\s*{', code)
        if mobj is None:
            break
        start, body_start = mobj.span()
        body, remaining = self._separate_at_paren(code[body_start - 1:])
        name = self._named_object(local_vars, self.extract_function_from_code(
            [x.strip() for x in mobj.group('args').split(',')],
            body, local_vars, *global_stack))
        code = code[:start] + name + remaining
    return self.build_function(argnames, code, local_vars, *global_stack)

def call_function(self, funcname, *args):
    return self.extract_function(funcname)(args)

def build_function(self, argnames, code, *global_stack):
    global_stack = list(global_stack) or [{}]
    argnames = tuple(argnames)

    def resf(args, kwargs={}, allow_recursion=100):
        global_stack[0].update(itertools.zip_longest(argnames, args, fillvalue=None))
        global_stack[0].update(kwargs)
        var_stack = LocalNameSpace(*global_stack)
        ret, should_abort = self.interpret_statement(code.replace('\n', ' '), var_stack, allow_recursion - 1)
        if should_abort:
            return ret
    return resf

